function countMirrorTriples(s: string): number {
  const seen = new Set<string>();
  const n = s.length;
  for (let i = 0; i < n; i++)
    for (let k = i + 2; k < n; k++)
      if (s[i] === s[k])
        for (let j = i + 1; j < k; j++) seen.add(s[i] + s[j]);
  return seen.size;
}

