function countMirrorTriples(s: string): number {
  const first = new Array(26).fill(-1), last = new Array(26).fill(-1);
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i) - 97;
    if (first[c] === -1) first[c] = i;
    last[c] = i;
  }
  let total = 0;
  for (let c = 0; c < 26; c++) {
    if (first[c] === -1 || last[c] - first[c] < 2) continue;
    const middle = new Set<string>();
    for (let j = first[c] + 1; j < last[c]; j++) middle.add(s[j]);
    total += middle.size;
  }
  return total;
}

